stageCss:
#stage .vp-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .vp-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .vp-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .vp-mark svg{ width:26px; height:26px; }
#stage .vp-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .vp-rt{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:7px; }
#stage .vp-rt b{
  color:#fff; font-family:var(--font-mono); font-size:30px; font-weight:700;
  font-variant-numeric:tabular-nums; transition:color .3s ease;
}
#stage .vp-rt.ok b{ color:var(--success); }
#stage .vp-rt.slow b{ color:var(--warn); }
#stage .vp-rt i{ color:var(--text-dim); font-size:19px; font-weight:600; font-style:normal; }
#stage .vp-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(58,160,255,.45); background:rgba(58,160,255,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .vp-health i{
  width:10px; height:10px; border-radius:50%; background:var(--accent-1);
  box-shadow:0 0 12px var(--accent-1); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .vp-health b{ color:var(--accent-1); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .vp-health.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.1); }
#stage .vp-health.ok i{ background:var(--success); box-shadow:0 0 12px var(--success); }
#stage .vp-health.ok b{ color:var(--success); }
#stage .vp-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .vp-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); animation-duration:.7s; }
#stage .vp-health.warn b{ color:var(--warn); }

/* ============================= SCENE STACK ============================= */
#stage .vp-body{ position:relative; flex:1; min-height:0; }
#stage .vp-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .vp-sc.on{ opacity:1; transform:none; }
#stage .vp-sc.whip{ animation:vp-whip .44s cubic-bezier(.19,1,.22,1); }

/* ============================ SCENE 1 · TAP ============================ */
#stage .vp-tap{ height:100%; display:flex; flex-direction:column; align-items:center; }

#stage .vp-fly{ position:relative; width:100%; height:248px; flex-shrink:0; }
#stage .vp-cloud{
  position:absolute; top:6px; left:50%; transform:translateX(-50%);
  padding:14px 30px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(58,160,255,.35); color:var(--text-dim);
  font-family:var(--font-mono); font-size:22px; font-weight:800; letter-spacing:3px;
  transition:border-color .35s ease, color .35s ease, box-shadow .35s ease, background .35s ease;
}
#stage .vp-cloud.on{
  border-color:rgba(58,160,255,.75); color:#fff;
  background:linear-gradient(90deg, rgba(58,160,255,.22), rgba(34,211,238,.12));
  box-shadow:0 0 0 1px rgba(58,160,255,.3), 0 0 70px rgba(58,160,255,.35);
}
#stage .vp-pkt{
  position:absolute; bottom:4px; left:50%; opacity:0;
  transform:translateX(-50%) scale(.8);
  padding:12px 24px; border-radius:14px; white-space:nowrap;
  background:rgba(58,160,255,.16); border:1.5px solid rgba(58,160,255,.6); color:#fff;
  font-family:var(--font-mono); font-size:23px; font-weight:700;
  box-shadow:0 0 34px rgba(58,160,255,.45);
}
#stage .vp-pkt.go{ animation:vp-fly 1.25s cubic-bezier(.4,0,.2,1) forwards; }

#stage .vp-phone{
  position:relative; width:432px; height:648px; flex-shrink:0;
  display:flex; flex-direction:column; gap:16px; padding:20px;
  border-radius:44px; border:3px solid #2A3550;
  background:linear-gradient(180deg,#141B2B,#0E1420);
  box-shadow:0 26px 80px rgba(0,0,0,.6), 0 0 0 1px rgba(58,160,255,.14);
  transition:box-shadow .3s ease, border-color .3s ease;
}
#stage .vp-phone.lit{
  border-color:rgba(58,160,255,.6);
  box-shadow:0 26px 80px rgba(0,0,0,.6), 0 0 0 1px rgba(58,160,255,.4), 0 0 80px rgba(58,160,255,.28);
}
#stage .vp-ph-bar{
  height:52px; flex-shrink:0; display:flex; align-items:center; gap:12px;
  padding:0 18px; border-radius:16px;
  background:rgba(14,20,32,.9); border:1.5px solid var(--border);
}
#stage .vp-ph-bar i{
  width:11px; height:11px; border-radius:50%; flex-shrink:0;
  background:var(--success); box-shadow:0 0 10px var(--success);
}
#stage .vp-ph-bar span{ color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600; }
#stage .vp-ph-hero{
  height:238px; flex-shrink:0; border-radius:24px;
  display:flex; align-items:center; justify-content:center;
  background:radial-gradient(circle at 50% 40%, rgba(58,160,255,.2), transparent 65%), rgba(20,27,43,.9);
  border:1.5px solid var(--border);
}
#stage .vp-ph-hero span{ font-size:128px; line-height:1; animation:msd-float 3.6s ease-in-out infinite; }
#stage .vp-ph-name{ color:#fff; font-size:31px; font-weight:800; letter-spacing:.4px; }
#stage .vp-ph-price{ color:var(--accent-1); font-family:var(--font-mono); font-size:46px; font-weight:800; line-height:1; }
#stage .vp-ph-price em{ color:var(--text-dim); font-style:normal; font-size:21px; font-weight:600; }
#stage .vp-ph-cta{
  position:relative; overflow:hidden; margin-top:auto;
  height:92px; flex-shrink:0; border-radius:22px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(90deg, var(--accent-2), var(--accent-1));
  color:#fff; font-size:28px; font-weight:800; letter-spacing:2.4px;
  box-shadow:0 0 46px rgba(58,160,255,.4);
}
#stage .vp-ph-cta.tap{ animation:vp-press .34s cubic-bezier(.22,1,.36,1); }
#stage .vp-ripple{
  position:absolute; left:50%; top:50%; width:24px; height:24px; margin:-12px 0 0 -12px;
  border-radius:50%; background:rgba(255,255,255,.55); opacity:0; pointer-events:none;
}
#stage .vp-ripple.go{ animation:vp-ripple .7s ease-out; }
#stage .vp-finger{
  position:absolute; right:52px; bottom:-26px; font-size:74px; line-height:1;
  opacity:0; pointer-events:none; filter:drop-shadow(0 10px 20px rgba(0,0,0,.6));
}
#stage .vp-finger.go{ animation:vp-tap 1.1s cubic-bezier(.22,1,.36,1) forwards; }

/* ======================= SCENE 2 · THE ARCHITECTURE ==================== */
#stage .vp-rail, #stage .vp-blob{
  height:100%; display:flex; flex-direction:column; justify-content:center;
}
/* Fixed height, because the response bracket is positioned against it in px
   and a diagram that reflows would take the return path with it. */
#stage .vp-arch{ position:relative; height:772px; flex-shrink:0; }
#stage .vp-flow{ width:calc(100% - 96px); display:flex; flex-direction:column; }

#stage .vp-node{
  height:122px; flex-shrink:0; display:flex; align-items:center; gap:18px;
  padding:0 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  opacity:.46; filter:saturate(.4);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, box-shadow .3s ease;
}
#stage .vp-node.live{ opacity:1; filter:none; }
#stage .vp-node.hot{
  opacity:1; filter:none; border-color:rgba(58,160,255,.7);
  box-shadow:0 0 0 1px rgba(58,160,255,.3), 0 0 54px rgba(58,160,255,.24);
}
#stage .vp-node.hit{
  opacity:1; filter:none; border-color:rgba(63,185,80,.65);
  box-shadow:0 0 0 1px rgba(63,185,80,.26), 0 0 54px rgba(63,185,80,.2);
}
#stage .vp-node.miss{
  opacity:1; filter:none; border-color:rgba(240,166,74,.65);
  box-shadow:0 0 0 1px rgba(240,166,74,.26), 0 0 54px rgba(240,166,74,.2);
}
#stage .vp-n-ic{
  width:60px; height:60px; border-radius:17px; flex-shrink:0; font-size:32px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .vp-node.hot .vp-n-ic{ border-color:rgba(58,160,255,.6); background:rgba(58,160,255,.16); }
#stage .vp-node.hit .vp-n-ic{ border-color:rgba(63,185,80,.6); background:rgba(63,185,80,.14); }
#stage .vp-node.miss .vp-n-ic{ border-color:rgba(240,166,74,.6); background:rgba(240,166,74,.14); }
#stage .vp-n-t{ display:flex; flex-direction:column; gap:7px; min-width:0; }
#stage .vp-n-t b{ color:#fff; font-size:29px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .vp-n-t i{
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600;
  font-style:normal; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .vp-n-b{
  margin-left:auto; flex-shrink:0; padding:9px 18px; border-radius:100px; white-space:nowrap;
  border:1.5px solid var(--border); background:rgba(14,20,32,.8); color:var(--text-dim);
  font-family:var(--font-mono); font-size:20px; font-weight:700;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .vp-node.hot .vp-n-b{ border-color:rgba(58,160,255,.55); background:rgba(58,160,255,.14); color:var(--accent-1); }
#stage .vp-node.hit .vp-n-b{ border-color:rgba(63,185,80,.55); background:rgba(63,185,80,.14); color:var(--success); }
#stage .vp-node.miss .vp-n-b{ border-color:rgba(240,166,74,.6); background:rgba(240,166,74,.14); color:var(--warn); }

/* The connector. The dots run in the direction the data is actually moving,
   which is the cheapest way to make a static diagram read as a flow. Centred
   rather than under the icons, so the column lines up with the fork stem. */
#stage .vp-link{
  position:relative; height:46px; flex-shrink:0;
}
#stage .vp-link::before{
  content:""; position:absolute; left:50%; top:0; bottom:0; width:3px;
  margin-left:-1.5px; border-radius:2px; background:var(--border);
  transition:background .3s ease;
}
#stage .vp-link.down::before, #stage .vp-link.up::before{ background:rgba(58,160,255,.4); }
#stage .vp-link.back::before{ background:rgba(63,185,80,.4); }
#stage .vp-link i{
  position:absolute; left:50%; margin-left:-7px; top:-7px;
  width:14px; height:14px; border-radius:50%; opacity:0;
  background:var(--accent-1); box-shadow:0 0 16px var(--accent-1);
}
#stage .vp-link.down i{ animation:vp-down 1s linear infinite; }
#stage .vp-link.up i{ animation:vp-up 1s linear infinite; }
#stage .vp-link.back i{ background:var(--success); box-shadow:0 0 16px var(--success); }
#stage .vp-link i:nth-child(2){ animation-delay:.33s; }
#stage .vp-link i:nth-child(3){ animation-delay:.66s; }
#stage .vp-link b{
  position:absolute; left:calc(50% + 30px); top:50%; transform:translateY(-50%);
  padding:6px 16px; border-radius:9px; white-space:nowrap; opacity:0;
  border:1.5px solid var(--border); background:rgba(14,20,32,.9); color:var(--text-dim);
  font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:1.6px;
  transition:opacity .25s ease;
}
#stage .vp-link b.show{ opacity:1; }
#stage .vp-link b.good{ border-color:rgba(63,185,80,.6); background:rgba(63,185,80,.14); color:var(--success); }
#stage .vp-link b.warn{ border-color:rgba(240,166,74,.6); background:rgba(240,166,74,.14); color:var(--warn); }

/* ------------------------------------------------------------- the fork -- */
/* Stem down from the API, a crossbar, then one arm into each answer. The two
   arms are what stop Redis and SQL reading as "step four" and "step five". */
#stage .vp-fork{
  position:relative; height:64px; flex-shrink:0;
  opacity:.4; transition:opacity .3s ease;
}
#stage .vp-fork.on{ opacity:1; }
#stage .vp-fk-stem{
  position:absolute; left:50%; margin-left:-1.5px; top:0; width:3px; height:16px;
  border-radius:2px; background:rgba(58,160,255,.5);
}
#stage .vp-fk-bar{
  position:absolute; left:22.3%; right:22.3%; top:16px; height:3px;
  border-radius:2px; background:rgba(58,160,255,.5);
}
#stage .vp-fk-arm{
  position:absolute; top:16px; width:3px; height:48px; margin-left:-1.5px;
  border-radius:2px; background:var(--border); transition:background .3s ease;
}
#stage .vp-fk-arm.l{ left:22.3%; }
#stage .vp-fk-arm.r{ left:77.7%; }
#stage .vp-fk-arm.dn, #stage .vp-fk-arm.up{ background:rgba(58,160,255,.6); }
#stage .vp-fk-arm.good{ background:rgba(63,185,80,.65); }
#stage .vp-fk-arm.warn{ background:rgba(240,166,74,.65); }
#stage .vp-fk-arm i{
  position:absolute; left:50%; margin-left:-7px; top:0;
  width:14px; height:14px; border-radius:50%; opacity:0;
  background:var(--accent-1); box-shadow:0 0 16px var(--accent-1);
}
#stage .vp-fk-arm.dn i{ animation:vp-armdn .9s linear infinite; }
#stage .vp-fk-arm.up i{ animation:vp-armup .9s linear infinite; }
#stage .vp-fk-arm.good i{ background:var(--success); box-shadow:0 0 16px var(--success); }
#stage .vp-fk-arm.warn i{ background:var(--warn); box-shadow:0 0 16px var(--warn); }
#stage .vp-fk-arm i:nth-child(2){ animation-delay:.45s; }
#stage .vp-fk-tag{
  position:absolute; left:50%; top:28px; transform:translateX(-50%);
  padding:6px 16px; border-radius:9px; white-space:nowrap;
  border:1.5px solid rgba(58,160,255,.45); background:var(--bg-deep); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:1.8px;
}

/* ---------------------------------------------------- the two answers ---- */
#stage .vp-pair{ display:flex; align-items:stretch; height:250px; flex-shrink:0; }
/* Declared after .vp-node so it wins the layout while keeping every state
   colour (.hot / .hit / .miss) the row version already defines. */
#stage .vp-tile{
  flex:1; min-width:0; height:auto; text-align:center;
  flex-direction:column; align-items:center; justify-content:center; gap:13px;
  padding:20px 18px; border-radius:26px;
}
#stage .vp-tile .vp-n-ic{ width:74px; height:74px; border-radius:21px; font-size:38px; }
#stage .vp-tile b{ color:#fff; font-size:29px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .vp-tile i{
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600;
  font-style:normal; line-height:1.35; max-width:100%;
}
#stage .vp-tile .vp-n-b{ margin-left:0; }

/* The sideways hop between them: a miss falls right, the write-back goes left. */
#stage .vp-cross{ position:relative; width:96px; flex-shrink:0; }
#stage .vp-cross::before{
  content:""; position:absolute; left:0; right:0; top:50%; margin-top:-1.5px;
  height:3px; border-radius:2px; background:var(--border); transition:background .3s ease;
}
#stage .vp-cross.warn::before{ background:rgba(240,166,74,.6); }
#stage .vp-cross.good::before{ background:rgba(63,185,80,.6); }
#stage .vp-cross i{
  position:absolute; top:50%; margin-top:-7px; left:0;
  width:14px; height:14px; border-radius:50%; opacity:0;
  background:var(--accent-1); box-shadow:0 0 16px var(--accent-1);
}
#stage .vp-cross.rt i{ animation:vp-rt .95s linear infinite; }
#stage .vp-cross.lt i{ animation:vp-lt .95s linear infinite; }
#stage .vp-cross.warn i{ background:var(--warn); box-shadow:0 0 16px var(--warn); }
#stage .vp-cross.good i{ background:var(--success); box-shadow:0 0 16px var(--success); }
#stage .vp-cross i:nth-child(2){ animation-delay:.31s; }
#stage .vp-cross i:nth-child(3){ animation-delay:.62s; }

/* --------------------------------------------------- the response path --- */
/* A bracket up the right edge. Keeping the return off the request column is
   what stops the diagram implying the answer travels downhill too. */
#stage .vp-return{
  position:absolute; right:8px; top:61px; bottom:375px; width:72px;
  border:3px solid var(--border); border-left:0; border-radius:0 30px 30px 0;
  opacity:.45; transition:opacity .3s ease, border-color .3s ease, box-shadow .3s ease;
}
#stage .vp-return.on{ opacity:1; }
#stage .vp-return.good{
  border-color:rgba(63,185,80,.7); box-shadow:0 0 40px rgba(63,185,80,.16);
}
#stage .vp-return i{
  position:absolute; right:-7px; bottom:0;
  width:14px; height:14px; border-radius:50%; opacity:0;
  background:var(--success); box-shadow:0 0 16px var(--success);
}
#stage .vp-return.on i{ animation:vp-rise 1.15s linear infinite; }
#stage .vp-return i:nth-child(2){ animation-delay:.38s; }
#stage .vp-return i:nth-child(3){ animation-delay:.76s; }
#stage .vp-return b{
  position:absolute; left:50%; top:50%; transform:translate(-50%,-50%) rotate(90deg);
  color:var(--text-dim); font-family:var(--font-mono); font-size:18px;
  font-weight:800; letter-spacing:3px; white-space:nowrap;
  transition:color .3s ease;
}
#stage .vp-return.good b{ color:var(--success); }

#stage .vp-verdict{
  height:86px; flex-shrink:0; margin-top:14px;
  display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.75); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .vp-verdict b{
  padding:7px 16px; border-radius:9px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:2px;
}
#stage .vp-verdict span{ color:var(--text-primary); font-size:23px; font-weight:600; line-height:1.3; }
#stage .vp-verdict em{
  margin-left:auto; flex-shrink:0; color:#fff; font-style:normal;
  font-family:var(--font-mono); font-size:28px; font-weight:800; font-variant-numeric:tabular-nums;
}
#stage .vp-verdict.good{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.09); }
#stage .vp-verdict.good b{ background:rgba(63,185,80,.2); color:var(--success); }
#stage .vp-verdict.good em{ color:var(--success); }
#stage .vp-verdict.warn{ border-color:rgba(240,166,74,.5); background:rgba(240,166,74,.09); }
#stage .vp-verdict.warn b{ background:rgba(240,166,74,.2); color:var(--warn); }
#stage .vp-verdict.warn em{ color:var(--warn); }

/* ============================ SCENE 3 · BLOB =========================== */
/* Left to right, deliberately across the grain of the vertical scenes. */
#stage .vp-row{ display:flex; align-items:stretch; height:452px; flex-shrink:0; }
#stage .vp-tile.tall{ gap:20px; padding:26px 20px; }
#stage .vp-tile.tall .vp-n-ic{ width:96px; height:96px; border-radius:26px; font-size:48px; }
#stage .vp-tile.tall b{ font-size:27px; }

#stage .vp-hlink{ position:relative; width:76px; flex-shrink:0; }
#stage .vp-hlink::before{
  content:""; position:absolute; left:0; right:0; top:50%; margin-top:-1.5px;
  height:3px; border-radius:2px; background:var(--border); transition:background .3s ease;
}
#stage .vp-hlink.good::before{ background:rgba(63,185,80,.6); }
#stage .vp-hlink i{
  position:absolute; top:50%; margin-top:-7px; left:0;
  width:14px; height:14px; border-radius:50%; opacity:0;
  background:var(--accent-1); box-shadow:0 0 16px var(--accent-1);
}
#stage .vp-hlink.on i{ animation:vp-hrt 1s linear infinite; }
#stage .vp-hlink.good i{ background:var(--success); box-shadow:0 0 16px var(--success); }
#stage .vp-hlink i:nth-child(2){ animation-delay:.33s; }
#stage .vp-hlink i:nth-child(3){ animation-delay:.66s; }

#stage .vp-shot-img{
  width:96px; height:96px; border-radius:26px; flex-shrink:0; font-size:48px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(14,20,32,.9); border:1.5px dashed var(--border);
  opacity:.16; filter:blur(9px);
  transition:opacity .45s ease, filter .45s ease, border-color .45s ease, background .45s ease;
}
#stage .vp-shot-img.loaded{
  opacity:1; filter:none; border-style:solid; border-color:rgba(58,160,255,.5);
  background:radial-gradient(circle at 50% 40%, rgba(58,160,255,.24), transparent 68%), rgba(20,27,43,.9);
}

#stage .vp-facts{ display:flex; gap:14px; margin-top:18px; flex-shrink:0; }
#stage .vp-fact{
  flex:1; text-align:center; padding:20px 12px; border-radius:18px; white-space:nowrap;
