#stage .vp-map{ height:100%; display:flex; flex-direction:column; justify-content:center; gap:22px; }
#stage .vp-cols{ display:flex; gap:18px; align-items:stretch; }
#stage .vp-col{
  flex:1; min-width:0; display:flex; flex-direction:column; align-items:center;
  padding:20px 16px; border-radius:26px;
}
#stage .vp-col#vp-col-data{
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.14), transparent 62%), rgba(20,27,43,.6);
