}
#stage .vp-col#vp-col-files{
  background:radial-gradient(circle at 50% 0%, rgba(34,211,238,.12), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(34,211,238,.45);
  justify-content:flex-start;
}
#stage .vp-col-h{
  margin-bottom:14px; font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:2.6px;
}
#stage #vp-col-data .vp-col-h{ color:var(--accent-1); }
#stage #vp-col-files .vp-col-h{ color:var(--accent-cyan); }
#stage .vp-mini{
  width:100%; height:72px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 16px; border-radius:16px; white-space:nowrap;
