#stage .vp-mini.sm{ flex:1 1 0; width:auto; min-width:0; padding:0 12px; gap:10px; font-size:19px; }
#stage .vp-mini.sm span{ font-size:26px; }
#stage .vp-tick{
  width:3px; height:20px; flex-shrink:0; border-radius:2px; background:rgba(58,160,255,.45);
}
#stage .vp-grid{ display:flex; flex-wrap:wrap; gap:14px; }
#stage .vp-cell{
  flex:1 1 44%; display:flex; align-items:center; gap:14px;
  padding:18px 20px; border-radius:18px; white-space:nowrap;
