var VP = window.__VP || (window.__VP = {});

// Node and link state is set from every stage rather than accumulated,
// because the reel loops and a leftover green border reads as a bug.
VP.NODES = ['user','cdn','api','redis','sql','blob','edge','shot'];
VP.LINKS = ['1','2'];

VP.reset = function(){
  VP.NODES.forEach(function(id){
    MSD.cls('#vp-n-' + id, 'hot', false);
    MSD.cls('#vp-n-' + id, 'hit', false);
    MSD.cls('#vp-n-' + id, 'miss', false);
    MSD.cls('#vp-n-' + id, 'live', false);
  });
  VP.LINKS.forEach(function(n){
    MSD.cls('#vp-l-' + n, 'down', false);
    MSD.cls('#vp-l-' + n, 'up', false);
    MSD.cls('#vp-l-' + n, 'back', false);
    var b = MSD.q('#vp-lb-' + n);
    if(b){ b.textContent = ''; b.className = ''; }
  });
  VP.arm('redis', '', '');
  VP.arm('sql', '', '');
  VP.cross('', '');
  VP.ret(false, '');
  VP.fork(false);
  VP.hlink('1', false, '');
  VP.hlink('2', false, '');
};

/** One prong of the fork. dir: '' | 'dn' | 'up'. tone: '' | 'good' | 'warn'. */
VP.arm = function(which, dir, tone){
  MSD.q('#vp-fk-' + which).className =
    'vp-fk-arm ' + (which === 'redis' ? 'l' : 'r') +
    (dir ? ' ' + dir : '') + (tone ? ' ' + tone : '');
};
/** The sideways hop between cache and database. dir: '' | 'rt' | 'lt'. */
VP.cross = function(dir, tone){
  MSD.q('#vp-cross').className = 'vp-cross' + (dir ? ' ' + dir : '') + (tone ? ' ' + tone : '');
};
/** The response bracket up the right edge. */
VP.ret = function(on, tone){
  MSD.q('#vp-return').className = 'vp-return' + (on ? ' on' : '') + (tone ? ' ' + tone : '');
};
VP.fork = function(on, tag){
  MSD.cls('#vp-fork', 'on', !!on);
  if(tag != null) MSD.q('#vp-fk-tag').textContent = tag;
};
/** A horizontal hop in the Blob scene. */
VP.hlink = function(n, on, tone){
  MSD.q('#vp-h-' + n).className = 'vp-hlink' + (on ? ' on' : '') + (tone ? ' ' + tone : '');
};

/** state: '' | 'live' | 'hot' | 'hit' | 'miss' */
VP.node = function(id, state, badge, sub){
  MSD.cls('#vp-n-' + id, 'hot', state === 'hot');
  MSD.cls('#vp-n-' + id, 'hit', state === 'hit');
  MSD.cls('#vp-n-' + id, 'miss', state === 'miss');
  MSD.cls('#vp-n-' + id, 'live', state !== '');
  if(badge != null) MSD.q('#vp-b-' + id).textContent = badge;
  if(sub != null) MSD.q('#vp-s-' + id).textContent = sub;
};

/** dir: '' | 'down' | 'up' | 'back' (an upward return, drawn green) */
VP.link = function(n, dir, label, tone){
  MSD.cls('#vp-l-' + n, 'down', dir === 'down');
  MSD.cls('#vp-l-' + n, 'up', dir === 'up' || dir === 'back');
  MSD.cls('#vp-l-' + n, 'back', dir === 'back');
  var b = MSD.q('#vp-lb-' + n);
  b.textContent = label || '';
  b.className = label ? 'show ' + (tone || '') : '';
};

VP.verdict = function(label, text, ms, tone){
  MSD.cls('#vp-verdict', 'good', tone === 'good');
  MSD.cls('#vp-verdict', 'warn', tone === 'warn');
  MSD.q('#vp-v-l').textContent = label;
  MSD.q('#vp-v-t').textContent = text;
  MSD.q('#vp-v-n').textContent = ms;
};

VP.header = function(app, ms, tone, health){
  MSD.q('#vp-app').textContent = app;
  MSD.q('#vp-rt-n').textContent = ms;
  MSD.cls('#vp-rt', 'ok', tone === 'ok');
  MSD.cls('#vp-rt', 'slow', tone === 'slow');
  MSD.cls('#vp-health', 'ok', tone === 'ok');
  MSD.cls('#vp-health', 'warn', tone === 'slow');
  MSD.q('#vp-health-t').textContent = health;
};

VP.ramp = function(sel, from, to, ms){
  var el = MSD.q(sel); if(!el) return;
  var steps = Math.max(1, Math.round(ms / 50)), i = 0;
  var id = MSD.every(50, function(){
    i++;
    var p = Math.min(1, i / steps);
    el.textContent = Math.round(from + (to - from) * p);
    if(p >= 1) clearInterval(id);
  });
};

VP.scene = function(id, whip){
  MSD.cls('.vp-sc', 'on', false);
  MSD.cls('#vp-sc-' + id, 'on', true);
  MSD.cls('#vp-sc-' + id, 'whip', false);
  if(whip) MSD.after(20, function(){ MSD.cls('#vp-sc-' + id, 'whip', true); MSD.sfx.swipe(); });
};

VP.scene('tap');
VP.reset();
VP.header('msdevbuild.shop · product 123', '0', '', 'idle');
MSD.cls('#vp-phone', 'lit', false);
MSD.cls('#vp-cloud', 'on', false);
MSD.cls('#vp-pkt', 'go', false);
MSD.cls('#vp-finger', 'go', false);
MSD.cls('#vp-ripple', 'go', false);
MSD.cls('#vp-ph-cta', 'tap', false);

MSD.after(500, function(){ MSD.cls('#vp-finger', 'go', true); });
MSD.after(900, function(){
  MSD.cls('#vp-ph-cta', 'tap', true);
  MSD.cls('#vp-ripple', 'go', true);
  MSD.cls('#vp-phone', 'lit', true);
  MSD.sfx.pop();
});
MSD.after(1350, function(){ MSD.cls('#vp-pkt', 'go', true); MSD.sfx.whoosh(true); });
MSD.after(2350, function(){
  MSD.cls('#vp-cloud', 'on', true);
  MSD.sfx.lock();
  VP.header('msdevbuild.shop · request in flight', '4', '', 'in flight');
});

var VP = window.__VP;

VP.scene('rail', true);
VP.reset();
VP.header('msdevbuild.shop · GET /products/123', '4', '', 'at the edge');
VP.node('user', 'live', 'sent', 'one tap · GET /products/123');
VP.node('cdn', '', 'cache?', 'edge POP · closest to the phone');
VP.node('api', '', 'idle', 'the origin · your code');
VP.node('redis', '', 'cache?', 'in memory · product:123');
VP.node('sql', '', 'asleep', 'the source of truth');
VP.fork(false, 'CACHE-ASIDE');
VP.verdict('EDGE', 'Nothing on the phone knows which of these it is about to wake up.', '4 ms', '');

MSD.after(300, function(){
  VP.link('1', 'down');
  MSD.sfx.data(0);
});
MSD.after(1200, function(){
  VP.node('cdn', 'hot', 'checking');
  MSD.punch('#vp-n-cdn', 2);
  MSD.sfx.blip(2);
  VP.ramp('#vp-rt-n', 4, 12, 900);
});
MSD.after(2300, function(){
  VP.verdict('QUESTION', 'Do I already hold a copy of this response? Everything hangs on the answer.', '12 ms', '');
  MSD.q('#vp-b-cdn').textContent = 'CACHE HIT?';
  MSD.punch('#vp-verdict', 4);
});

var VP = window.__VP;

VP.scene('rail');
VP.reset();
VP.header('msdevbuild.shop · edge response', '12', '', 'checking');
VP.node('user', 'live', 'waiting', 'one tap · GET /products/123');
VP.node('cdn', 'hot', 'CACHE HIT?', 'edge POP · closest to the phone');
VP.node('api', '', 'idle', 'the origin · your code');
VP.node('redis', '', 'cache?', 'in memory · product:123');
VP.node('sql', '', 'asleep', 'the source of truth');
VP.fork(false, 'NOT REACHED');
VP.verdict('BEST CASE', 'The fastest request is the one that stops one hop in.', '12 ms', '');

MSD.after(500, function(){
  VP.node('cdn', 'hit', 'CACHE HIT');
  VP.link('1', 'back', 'CACHE HIT', 'good');
  MSD.punch('#vp-n-cdn', 3);
  MSD.sfx.ding();
});
MSD.after(1400, function(){
  VP.node('user', 'hit', 'page painted', 'product 123 · $99 · stock 24');
  VP.header('msdevbuild.shop · served from edge', '18', 'ok', 'cache hit');
  VP.verdict('HIT', 'Served from a POP near the phone. Your API, Redis and SQL all stayed asleep.', '18 ms', 'good');
  MSD.punch('#vp-n-user', 4);
  MSD.sfx.sparkle();
});
MSD.after(2700, function(){
  MSD.q('#vp-s-api').textContent = 'never called · zero load';
  MSD.punch('#vp-verdict', 5);
});

var VP = window.__VP;

VP.scene('rail');
VP.reset();
VP.header('msdevbuild.shop · forwarding', '12', '', 'cache miss');
VP.node('user', 'live', 'waiting', 'one tap · GET /products/123');
VP.node('cdn', 'miss', 'CACHE MISS', 'no copy held · or Cache-Control said no');
VP.node('api', '', 'idle', 'the origin · your code');
VP.node('redis', '', 'cache?', 'in memory · product:123');
VP.node('sql', '', 'asleep', 'the source of truth');
VP.fork(false, 'CACHE-ASIDE');
VP.link('1', 'down');
VP.verdict('MISS', 'The edge only caches what you let it cache. A live stock count usually is not that.', '12 ms', 'warn');

MSD.after(400, function(){
  MSD.punch('#vp-n-cdn', 1);
  MSD.sfx.error();
});
MSD.after(1200, function(){
  VP.link('2', 'down', 'TO ORIGIN', 'warn');
  VP.ramp('#vp-rt-n', 12, 26, 900);
  MSD.sfx.data(1);
});
MSD.after(2200, function(){
  VP.node('api', 'hot', 'receiving', 'GET /products/123 · app service');
  MSD.punch('#vp-n-api', 3);
  MSD.sfx.blip(3);
  VP.verdict('ORIGIN', 'Now, and only now, is this your application problem.', '26 ms', 'warn');
});

var VP = window.__VP;

VP.scene('rail');
VP.reset();
VP.header('msdevbuild.shop · app service', '26', '', 'in the API');
VP.node('user', 'live', 'waiting', 'one tap · GET /products/123');
VP.node('cdn', 'live', 'MISS', 'passed it through to the origin');
VP.node('api', 'hot', 'running', 'GET /products/123 · app service');
VP.node('redis', '', 'cache?', 'in memory · product:123');
VP.node('sql', '', 'asleep', 'the source of truth');
VP.fork(false, 'CACHE-ASIDE');
VP.verdict('CACHE-ASIDE', 'The pattern is one line of policy: read the cache, then the database.', '26 ms', '');

MSD.after(400, function(){
  MSD.q('#vp-s-api').textContent = 'building the response · needs product data';
  MSD.punch('#vp-n-api', 1);
  MSD.sfx.blip(1);
});
// The fork opens here — this is the stage where the request stops being a
// straight line and becomes a choice.
MSD.after(1300, function(){
  VP.fork(true, '1 · ASK THE CACHE');
  VP.arm('redis', 'dn');
  MSD.sfx.data(2);
});
MSD.after(2200, function(){
  VP.node('redis', 'hot', 'looking', 'in memory · product:123');
  MSD.punch('#vp-n-redis', 3);
  MSD.sfx.blip(3);
  VP.ramp('#vp-rt-n', 26, 28, 600);
});
MSD.after(3100, function(){
  VP.verdict('QUESTION', 'Is product 123 in memory right now? Same question, one layer deeper.', '28 ms', '');
  MSD.q('#vp-b-redis').textContent = 'CACHE HIT?';
  MSD.punch('#vp-verdict', 4);
});

var VP = window.__VP;

VP.scene('rail');
VP.reset();
VP.header('msdevbuild.shop · redis', '28', '', 'cache hit');
VP.node('user', 'live', 'waiting', 'one tap · GET /products/123');
VP.node('cdn', 'live', 'MISS', 'passed it through to the origin');
VP.node('api', 'live', 'waiting', 'GET product:123 · cache-aside');
VP.node('redis', 'hot', 'CACHE HIT?', 'in memory · product:123');
VP.node('sql', '', 'asleep', 'the source of truth');
VP.fork(true, '1 · ASK THE CACHE');
VP.arm('redis', 'dn');
VP.verdict('MEMORY', 'No disk, no query planner, no network hop out of the region.', '28 ms', '');

MSD.after(500, function(){
  VP.node('redis', 'hit', 'CACHE HIT', 'product:123 · $99 · stock 24');
  VP.arm('redis', 'up', 'good');
  MSD.punch('#vp-n-redis', 3);
  MSD.sfx.ding();
});
MSD.after(1500, function(){
  VP.node('api', 'hit', '200 OK', 'response built · SQL not touched');
  // The answer leaves on the response bracket, not back down the column.
  VP.ret(true, 'good');
  MSD.sfx.blip(4);
  VP.ramp('#vp-rt-n', 28, 41, 700);
});
MSD.after(2400, function(){
  VP.node('cdn', 'hit', 'now cached', 'holds this response for next time');
  VP.node('user', 'hit', 'page painted', '$99 · in stock 24 · 41 ms');
  VP.header('msdevbuild.shop · served', '41', 'ok', 'fast');
  VP.verdict('FAST', 'Forty-one milliseconds, and the database never knew this request existed.', '41 ms', 'good');
  MSD.sfx.sparkle();
});
MSD.after(3400, function(){ MSD.punch('#vp-n-user', 5); });

var VP = window.__VP;

VP.scene('rail');
VP.reset();
VP.header('msdevbuild.shop · redis', '28', '', 'cache miss');
VP.node('user', 'live', 'waiting', 'one tap · GET /products/123');
VP.node('cdn', 'live', 'MISS', 'passed it through to the origin');
VP.node('api', 'live', 'waiting', 'GET product:123 · cache-aside');
VP.node('redis', 'miss', 'CACHE MISS', 'key not found · TTL expired');
VP.node('sql', '', 'asleep', 'the source of truth');
VP.fork(true, '1 · ASK THE CACHE');
VP.arm('redis', 'dn', 'warn');
VP.verdict('MISS', 'First request after a deploy, or sixty seconds after the last one. Same result.', '28 ms', 'warn');

MSD.after(400, function(){
  MSD.punch('#vp-n-redis', 1);
  MSD.sfx.error();
});
