  VP.node('sql', 'hot', 'query in', 'SELECT · ProductId = 123');
  MSD.punch('#vp-n-sql', 3);
  MSD.sfx.blip(3);
  VP.verdict('FALL THROUGH', 'This is the slow path, and the whole point of the two layers above it.', '34 ms', 'warn');
});

