VP.reset();
VP.header('msdevbuild.shop · azure sql', '34', 'slow', 'querying');
VP.node('user', 'live', 'waiting', 'one tap · GET /products/123');
VP.node('cdn', 'live', 'MISS', 'passed it through to the origin');
VP.node('api', 'live', 'waiting', 'GET product:123 · cache-aside');
VP.node('redis', 'miss', 'MISS', 'key not found · TTL expired');
VP.node('sql', 'hot', 'query in', 'SELECT · ProductId = 123');
VP.fork(true, '2 · ONLY ON A MISS');
VP.arm('sql', 'dn', 'warn');
VP.cross('rt', 'warn');
VP.verdict('TRUTH', 'Every other box in this diagram is a copy. This one is the original.', '34 ms', 'warn');

