MSD.after(1000, function(){
  MSD.q('#vp-s-sql').textContent = 'index seek · PK_Products';
  MSD.sfx.tick();
  VP.ramp('#vp-rt-n', 34, 119, 1400);
});
MSD.after(2300, function(){
